{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "post-mi-intro-2wk",
    "name": "Post-MI Introductory Reconditioning — 2-Week Starter Block",
    "description": "A conservative 2-week introductory programme for a 58-year-old male, 6 months post-myocardial infarction, cleared by cardiac rehab for moderate-intensity exercise only. Heart rate capped at 115 bpm (~70% age-predicted max). No Valsalva, no maximal lifts. Full gym available.",
    "type": "hybrid",
    "visibility": "template",
    "metadata": {
      "created_at": "2025-01-01T00:00:00Z",
      "updated_at": "2025-01-01T00:00:00Z",
      "created_by": "personal_trainer",
      "tags": ["cardiac", "post-mi", "reconditioning", "moderate-intensity", "beginner", "older-adult"],
      "difficulty": "beginner",
      "estimated_duration_days": 14,
      "language": "en"
    },
    "goals": [
      {
        "id": "goal-cardiovascular-safety",
        "type": "primary",
        "category": "cardiovascular_health",
        "name": "Safe cardiovascular reconditioning",
        "description": "Re-establish aerobic base while keeping HR below 115 bpm at all times.",
        "target": {
          "metric": "resting_hr_bpm",
          "target_value": 65,
          "unit": "bpm",
          "measurement_type": "absolute"
        }
      },
      {
        "id": "goal-functional-strength",
        "type": "secondary",
        "category": "muscular_endurance",
        "name": "Rebuild foundational muscular endurance",
        "description": "Restore whole-body muscular endurance using light loads, controlled tempo, and open-glottis breathing.",
        "target": {
          "metric": "session_rpe_avg",
          "target_value": 5,
          "unit": "rpe_1-10",
          "measurement_type": "absolute"
        }
      }
    ],
    "requirements": {
      "min_age": 50,
      "max_age": 70,
      "fitness_level": ["beginner", "deconditioned"],
      "equipment": [
        { "id": "eq-treadmill", "name": "Treadmill", "required": true, "alternatives": ["stationary_bike", "rower"] },
        { "id": "eq-dumbbells", "name": "Dumbbells (light set)", "required": true },
        { "id": "eq-resistance-bands", "name": "Resistance bands", "required": false, "alternatives": ["cable_machine"] },
        { "id": "eq-bench", "name": "Adjustable bench", "required": true },
        { "id": "eq-cable-machine", "name": "Cable machine", "required": false },
        { "id": "eq-hrm", "name": "Heart rate monitor", "required": true }
      ],
      "contraindications": [
        {
          "condition": "icd10:I21",
          "severity": "high",
          "action": "require_clearance",
          "affected_activities": []
        },
        {
          "condition": "acsm:cardiac_rehab_phase_2",
          "severity": "high",
          "action": "modify",
          "affected_activities": []
        },
        {
          "condition": "valsalva_manoeuvre",
          "severity": "high",
          "action": "exclude",
          "affected_activities": []
        },
        {
          "condition": "maximal_effort_lifting",
          "severity": "high",
          "action": "exclude",
          "affected_activities": []
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 4,
        "min_minutes_per_day": 35,
        "max_minutes_per_day": 55
      }
    },
    "athlete_thresholds": {
      "hr_max_bpm": 162,
      "resting_hr_bpm": 65,
      "body_weight_kg": 85
    },
    "personalization": {
      "inputs": [
        {
          "id": "hrv_morning",
          "type": "number",
          "source": "wellness.hrv_rmssd_morning",
          "label": "Morning HRV (rMSSD ms)"
        },
        {
          "id": "sleep_hours",
          "type": "number",
          "source": "wellness.sleep_hours_last_night",
          "label": "Sleep hours last night"
        },
        {
          "id": "session_rpe_yesterday",
          "type": "number",
          "source": "wellness.session_rpe_yesterday",
          "label": "Yesterday session RPE"
        }
      ],
      "rules": [
        {
          "id": "rule-reduce-intensity-poor-sleep",
          "condition": {
            "field": "sleep_hours",
            "op": "lt",
            "value": 6
          },
          "actions": [
            {
              "type": "modify_intensity",
              "scope": "day",
              "note": "Reduce cardio target HR ceiling by 10 bpm and drop resistance sets by 1 if sleep < 6 h."
            }
          ]
        },
        {
          "id": "rule-rest-day-high-rpe",
          "condition": {
            "field": "session_rpe_yesterday",
            "op": "gte",
            "value": 7
          },
          "actions": [
            {
              "type": "substitute_day_type",
              "scope": "day",
              "note": "Convert next scheduled training day to active_recovery if yesterday RPE >= 7."
            }
          ]
        }
      ]
    },
    "phases": [
      {
        "id": "phase-intro",
        "name": "Introductory Reconditioning",
        "order": 1,
        "type": "base",
        "description": "Two weeks of low-to-moderate intensity work. Establish movement patterns, breathing discipline (no breath-holding), and aerobic base. HR must remain ≤115 bpm throughout. RPE target 3–5 on 1–10 scale.",
        "duration": { "value": 2, "unit": "weeks" },
        "weeks": [
          {
            "id": "week-1",
            "name": "Week 1 — Orientation",
            "order": 1,
            "is_deload": false,
            "days": [
              {
                "id": "w1d1",
                "day_of_week": 1,
                "type": "training",
                "name": "Day 1 — Cardio + Full-Body Resistance (A)",
                "estimated_duration_minutes": 45,
                "blocks": [
                  {
                    "id": "w1d1-warmup",
                    "type": "warmup",
                    "order": 1,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "w1d1-wu-walk",
                        "type": "cardio",
                        "name": "Easy treadmill walk",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 5, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 70, "max_bpm": 95 }
                          }
                        }
                      },
                      {
                        "id": "w1d1-wu-mobility",
                        "type": "recovery",
                        "name": "Dynamic mobility circuit",
                        "category": "warmup_mobility",
                        "prescription": {
                          "duration": { "value": 5, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "w1d1-wu-leg-swing",
                              "type": "recovery_exercise",
                              "name": "Leg swings (front-back)",
                              "modality": "dynamic_stretch",
                              "reps": 10,
                              "sides": "both",
                              "body_part": "hip_flexors"
                            },
                            {
                              "id": "w1d1-wu-arm-circle",
                              "type": "recovery_exercise",
                              "name": "Arm circles",
                              "modality": "dynamic_stretch",
                              "reps": 10,
                              "sides": "both",
                              "body_part": "rear_delts"
                            },
                            {
                              "id": "w1d1-wu-thoracic",
                              "type": "recovery_exercise",
                              "name": "Thoracic rotation (seated)",
                              "modality": "mobility_drill",
                              "reps": 8,
                              "sides": "both",
                              "body_part": "thoracic_spine"
                            }
                          ]
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d1-cardio",
                    "type": "main",
                    "order": 2,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "w1d1-treadmill",
                        "type": "cardio",
                        "name": "Moderate-pace treadmill walk",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 15, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 95, "max_bpm": 115 }
                          }
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d1-resistance",
                    "type": "main",
                    "order": 3,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "w1d1-goblet-squat",
                        "type": "exercise",
                        "exercise_ref": "goblet_squat",
                        "name": "Goblet squat (light dumbbell)",
                        "primary_muscles": ["quadriceps", "glutes"],
                        "secondary_muscles": ["hamstrings", "abs"],
                        "movement_pattern": "squat",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 8, "unit": "kg" }
                        }
                      },
                      {
                        "id": "w1d1-db-row",
                        "type": "exercise",
                        "exercise_ref": "dumbbell_single_arm_row",
                        "name": "Single-arm dumbbell row",
                        "primary_muscles": ["lats", "upper_back"],
                        "secondary_muscles": ["biceps", "rear_delts"],
                        "movement_pattern": "pull_horizontal",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 2, "pause_bottom": 1, "concentric": 2, "pause_top": 1 },
                          "weight": { "type": "absolute", "value": 8, "unit": "kg" }
                        }
                      },
                      {
                        "id": "w1d1-db-press",
                        "type": "exercise",
                        "exercise_ref": "dumbbell_chest_press_incline",
                        "name": "Incline dumbbell chest press (30° bench)",
                        "primary_muscles": ["chest"],
                        "secondary_muscles": ["front_delts", "triceps"],
                        "movement_pattern": "push_horizontal",
                        "target_rpe": 4,
                        "target_rir": 4,
                        "prescription": {
                          "type": "sets_reps",
                          "sets": 2,
                          "reps": { "min": 10, "max": 12 },
                          "rest": { "value": 90, "unit": "seconds" },
                          "tempo": { "eccentric": 3, "pause_bottom": 1, "concentric": 2, "pause_top": 0 },
                          "weight": { "type": "absolute", "value": 6, "unit": "kg" }
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d1-cooldown",
                    "type": "cooldown",
                    "order": 4,
                    "activities": [
                      {
                        "id": "w1d1-cd-walk",
                        "type": "cardio",
                        "name": "Cool-down treadmill walk",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 5, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 60, "max_bpm": 90 }
                          }
                        }
                      },
                      {
                        "id": "w1d1-cd-stretch",
                        "type": "recovery",
                        "name": "Static stretch — lower body",
                        "category": "cooldown_stretch",
                        "prescription": {
                          "duration": { "value": 5, "unit": "minutes" },
                          "exercises": [
                            {
                              "id": "w1d1-cd-quad",
                              "type": "recovery_exercise",
                              "name": "Standing quad stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "quadriceps"
                            },
                            {
                              "id": "w1d1-cd-calf",
                              "type": "recovery_exercise",
                              "name": "Standing calf stretch",
                              "modality": "static_stretch",
                              "hold_seconds": 30,
                              "sides": "both",
                              "intensity_rpe": 5,
                              "body_part": "calves"
                            }
                          ]
                        }
                      }
                    ]
                  }
                ]
              },
              {
                "id": "w1d2",
                "day_of_week": 2,
                "type": "rest",
                "name": "Day 2 — Rest",
                "estimated_duration_minutes": 0
              },
              {
                "id": "w1d3",
                "day_of_week": 3,
                "type": "training",
                "name": "Day 3 — Cardio Focus",
                "estimated_duration_minutes": 40,
                "blocks": [
                  {
                    "id": "w1d3-warmup",
                    "type": "warmup",
                    "order": 1,
                    "activities": [
                      {
                        "id": "w1d3-wu-walk",
