                    "order": 2,
                    "activities": [
                      {
                        "id": "w1d3-bike",
                        "type": "cardio",
                        "name": "Stationary bike — steady state",
                        "modality": "stationary_bike",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 20, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 95, "max_bpm": 115 }
                          }
                        }
                      }
                    ]
                  },
                  {
                    "id": "w1d3-cooldown",
                    "type": "cooldown",
                    "order": 3,
                    "activities": [
                      {
                        "id": "w1d3-cd-walk",
                        "type": "cardio",
                        "name": "Cool-down walk",
                        "modality": "treadmill_walk",
                        "prescription": {
                          "type": "continuous",
                          "duration": { "value": 5, "unit": "minutes" },
                          "intensity": {
                            "type": "bpm",
                            "target": { "min_bpm": 60, "max_bpm": 90 }
